package com.company.logicdelete.runtime;
import com.company.logicdelete.common.SqlUtils;import org.apache.ibatis.executor.Executor;import org.apache.ibatis.mapping.*;import org.apache.ibatis.session.RowBounds;import org.apache.ibatis.plugin.*;import java.time.OffsetDateTime;import java.util.*;
@Intercepts({@Signature(type=Executor.class,method="query",args={MappedStatement.class,Object.class,RowBounds.class,org.apache.ibatis.session.ResultHandler.class}),@Signature(type=Executor.class,method="update",args={MappedStatement.class,Object.class})})
public class LogicDeleteSqlTraceInterceptor implements Interceptor {private final RuntimeTraceProperties p;private final RuntimeSqlEventReporter reporter;public LogicDeleteSqlTraceInterceptor(RuntimeTraceProperties p,RuntimeSqlEventReporter r){this.p=p;reporter=r;}public Object intercept(Invocation i)throws Throwable{if(!p.isEnabled()||Math.random()>=p.getSampleRate())return i.proceed();long start=System.nanoTime();MappedStatement ms=(MappedStatement)i.getArgs()[0];Object parameter=i.getArgs().length>1?i.getArgs()[1]:null;String sql=ms.getBoundSql(parameter).getSql();try{return i.proceed();}finally{Map<String,Object>e=new LinkedHashMap<>();EntryContext.Value c=EntryContext.get();e.put("appName",p.getAppName());e.put("env",p.getEnv());e.put("traceId",c==null?UUID.randomUUID().toString().replace("-",""):c.traceId);e.put("entryType",c==null?"UNKNOWN":c.type);e.put("entryName",c==null?"UNKNOWN":c.name);e.put("sqlId",ms.getId());e.put("sqlCommandType",ms.getSqlCommandType().name());if(!"NONE".equalsIgnoreCase(p.getSqlOutputMode()))e.put("sqlHash",SqlUtils.sha256(sql));if("HASH_AND_SAMPLE".equalsIgnoreCase(p.getSqlOutputMode())||"FULL".equalsIgnoreCase(p.getSqlOutputMode())){String normalized=SqlUtils.normalize(sql);e.put("sqlSample","FULL".equalsIgnoreCase(p.getSqlOutputMode())?normalized:normalized.substring(0,Math.min(normalized.length(),p.getMaxSqlSampleLength())));}e.put("costMs",(System.nanoTime()-start)/1_000_000);e.put("executeTime",OffsetDateTime.now().toString());reporter.report(e);}}public Object plugin(Object target){return Plugin.wrap(target,this);}public void setProperties(Properties properties){}}
